function editRecord(record){if(submitting)return;active=record.plan.tool;refreshTool();for(const type of ['source','target']){if(urls[type])URL.revokeObjectURL(urls[type]);local[type]=record.files?.[type]||null;urls[type]=local[type]?URL.createObjectURL(local[type]):'';const desired=record.values[type]||'',fromDraft=type==='source'&&drafts.find(d=>!d.trashed&&d.assetId===record.plan.source.id);$('#studio-'+type).value=[...$('#studio-'+type).options].some(o=>o.value===desired)?desired:fromDraft?'draft:'+fromDraft.id:'';$('#studio-'+type+'-name').textContent=local[type]?.name||(type==='source'?'选择或拖入原始音频':'选择或拖入目标声音');preview(type,type==='source'||['speech','song'].includes(active));}$('#studio-cover-style').value=record.values.styles;$('#studio-cover-lyrics').value=record.values.lyrics;$('#studio-lyric-language').value=record.values.language||'zh';if(active==='cover')inference.restore(record);$('#studio-result-name').value=record.values.title;message('已载入参数，修改后可再次处理。');if(innerWidth<=780)$('.studio-editor').scrollIntoView({behavior:'smooth'});$('#studio-result-name').focus({preventScroll:true});}
