 async function trashStudio(id){const record=history.find(r=>r.id===id);if(!record?.job)return;recycleJob(workspaceState,record.job);drafts=workspaceState.drafts;generationSeen=workspaceState.generationSeen;if(studioPlayer.current()===id)studioPlayer.pause();if(focused===record)closePreview();saveCloudState('workspace',workspaceState);renderList();studioPlayer.refresh();try{await flushCloudState('workspace');message('已移入素材管理回收站，可以恢复。');}catch(error){message(error.message);}}
 $('#studio-list').onclick=e=>{const b=e.target.closest('[data-preview],[data-edit],[data-studio-play],[data-studio-trash]');if(!b)return;const id=b.dataset.preview||b.dataset.edit||b.dataset.studioPlay||b.dataset.studioTrash,record=history.find(r=>r.id===id);if(!record)return;if(b.dataset.studioTrash)trashStudio(id);else if(b.dataset.edit)editRecord(record);else if(b.dataset.studioPlay)studioPlayer.play(id);else showPlan(record);};
