for(const type of ['source','target']){const input=$('#studio-'+type+'-file'),drop=$('#studio-'+type+'-upload');function pick(file){if(submitting||!file)return;const max=32;if(!/\.(mp3|wav|flac)$/i.test(file.name)||!file.size||file.size>max*1048576){message('请选择不超过 '+max+' MB 的音频文件。');return;}if(urls[type])URL.revokeObjectURL(urls[type]);local[type]=file;urls[type]=URL.createObjectURL(file);$('#studio-'+type+'-name').textContent=file.name;$('#studio-'+type).value='';preview(type);invalidate();if(type==='source')inference.changed();}drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click();}};input.onchange=()=>{pick(input.files[0]);input.value='';};drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');pick(e.dataTransfer.files[0]);};$('#studio-'+type).onchange=()=>{preview(type);invalidate();if(type==='source')inference.changed();};}
